) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='组织与访问边界';

-- iam / 登录身份与授权
CREATE TABLE `admin_user_account_tab` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键、登录名、真实人员关联键',
  `login_name` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键、登录名、真实人员关联键',
  `person_key` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键、登录名、真实人员关联键',
  `identity_provider_code` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '认证来源与外部主体号；不存明文密码',
  `external_subject` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '认证来源与外部主体号；不存明文密码',
  `account_status` TINYINT NOT NULL COMMENT '账号状态及撤权会话版本；该字段独立码表待定义；不得使用概念流程标签或图示编号作为持久化枚举。',
  `auth_version` INT UNSIGNED NOT NULL COMMENT '账号状态及撤权会话版本',
  `memberships_json` JSON NOT NULL COMMENT '组织成员、有效期与成员状态',
  `grants_json` JSON NOT NULL COMMENT 'grant_id、角色版本、权限、数据范围、额度、批准及有效期',
  `mfa_status` TINYINT NOT NULL COMMENT 'MFA状态和最近认证时刻；该字段独立码表待定义；不得使用概念流程标签或图示编号作为持久化枚举。',
  `last_authenticated_at` DATETIME(3) NULL COMMENT 'MFA状态和最近认证时刻',
  `created_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'UTC 创建/更新时间',
  `updated_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'UTC 创建/更新时间',
  `disabled_at` DATETIME(3) NULL COMMENT '停用时间及操作者引用',
  `disabled_by` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '停用时间及操作者引用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_admin_user_account_login_name` (`login_name`) COMMENT '业务唯一键 / 幂等键',
  UNIQUE KEY `uk_admin_user_account_person_key` (`person_key`) COMMENT '业务唯一键 / 幂等键'
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='登录身份与授权';

