-- workflow / 任务定义
CREATE TABLE `batch_task_tab` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键、任务码及定义版本',
  `task_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键、任务码及定义版本',
  `version_number` INT NOT NULL COMMENT '主键、任务码及定义版本',
  `task_name` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '任务名与定时/事件/人工触发类型',
  `task_type_code` TINYINT NOT NULL COMMENT '任务名与定时/事件/人工触发类型',
  `schedule_expression` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '调度规则和明确时区',
  `timezone` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '调度规则和明确时区',
  `handler_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '处理器及输入结构版本',
  `input_schema_version` INT NOT NULL COMMENT '处理器及输入结构版本',
  `retry_policy_json` JSON NOT NULL COMMENT '退避重试策略与超时',
  `timeout_seconds` INT UNSIGNED NOT NULL COMMENT '退避重试策略与超时',
  `task_status` TINYINT UNSIGNED NOT NULL COMMENT '启用/停用；该字段独立码表待定义；不得使用概念流程标签或图示编号作为持久化枚举。',
  `created_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'UTC 维护时间',
  `updated_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT 'UTC 维护时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_batch_task_task_code_version_number` (`task_code`, `version_number`) COMMENT '业务唯一键 / 幂等键'
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='任务定义';

-- workflow / 任务执行记录
CREATE TABLE `batch_task_execute_log_tab` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键及单次执行业务号；每次执行尝试单独记录一行',
  `execute_number` VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键及单次执行业务号；每次执行尝试单独记录一行',
  `task_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '任务定义及执行时使用的定义版本',
  `definition_version` INT UNSIGNED NOT NULL COMMENT '任务定义及执行时使用的定义版本',
  `business_key` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '业务对象键、下游幂等键及尝试序号',
  `idempotency_key` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '业务对象键、下游幂等键及尝试序号',
  `attempt_number` INT UNSIGNED NOT NULL COMMENT '业务对象键、下游幂等键及尝试序号',
  `input_snapshot_json` JSON NOT NULL COMMENT '本次执行输入快照结构见领域设计文档 §11',
  `task_status` TINYINT UNSIGNED NOT NULL COMMENT '运行中/成功/失败/超时/取消；该字段独立码表待定义；不得使用概念流程标签或图示编号作为持久化枚举。',
  `worker_reference` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '执行节点和链路追踪标识',
  `trace_id` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '执行节点和链路追踪标识',
  `started_at` DATETIME(3) NULL COMMENT '本次尝试起止时间及计划重试时间',
  `finished_at` DATETIME(3) NULL COMMENT '本次尝试起止时间及计划重试时间',
  `next_retry_at` DATETIME(3) NULL COMMENT '本次尝试起止时间及计划重试时间',
  `error_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '失败分类、脱敏诊断信息及业务结果引用',
  `error_message` VARCHAR(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '失败分类、脱敏诊断信息及业务结果引用',
  `result_reference` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '失败分类、脱敏诊断信息及业务结果引用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_batch_task_execute_log_execute_number` (`execute_number`) COMMENT '业务唯一键 / 幂等键',
  UNIQUE KEY `uk_batch_task_execute_log_task_co_6a47eb1d` (`task_code`, `business_key`, `attempt_number`) COMMENT '业务唯一键 / 幂等键',
  KEY `idx_batch_task_execute_log_task_s_a3c20561` (`task_status`, `started_at`) COMMENT '查询索引 / 逻辑引用'
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='任务执行记录';

