  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键、投递引用及尝试号',
  `delivery_number` VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键、投递引用及尝试号',
  `attempt_number` INT NOT NULL COMMENT '主键、投递引用及尝试号',
  `provider_code` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '服务商及其消息号',
  `provider_message_number` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '服务商及其消息号',
  `attempt_status` TINYINT UNSIGNED NOT NULL COMMENT '已请求/已接受/失败/送达/未知；该字段独立码表待定义；不得使用概念流程标签或图示编号作为持久化枚举。',
  `requested_at` DATETIME(3) NOT NULL COMMENT 'UTC 尝试时间',
  `completed_at` DATETIME(3) NULL COMMENT 'UTC 尝试时间',
  `failure_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '失败原因与受控分类',
  `failure_reason` VARCHAR(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '失败原因与受控分类',
  `retry_after_at` DATETIME(3) NULL COMMENT '下一次重试时间',
  `provider_response_hash` CHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '回执摘要',
  `created_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'UTC 落库时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_message_delivery_attempt_deliv_6094373a` (`delivery_number`, `attempt_number`) COMMENT '业务唯一键 / 幂等键'
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='投递尝试';

-- audit / 安全与业务操作审计
CREATE TABLE `admin_audit_log_tab` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键与链路追踪标识',
  `trace_id` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键与链路追踪标识',
  `actor_type` TINYINT NOT NULL COMMENT '人工/系统来源、操作者引用和权限快照',
  `actor_reference` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '人工/系统来源、操作者引用和权限快照',
  `actor_role_snapshot` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '人工/系统来源、操作者引用和权限快照',
  `action_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '动作码及目标领域',
  `target_context_code` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '动作码及目标领域',
  `target_type` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '业务对象类型和稳定业务编号',
  `target_number` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '业务对象类型和稳定业务编号',
  `before_data` JSON NULL COMMENT '脱敏后的变更摘要；非完整敏感数据',
  `after_data` JSON NULL COMMENT '脱敏后的变更摘要；非完整敏感数据',
  `client_ip` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '来源网络/设备标识',
  `source_device_reference` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '来源网络/设备标识',
  `operation_result` TINYINT NOT NULL COMMENT '成功/拒绝/失败/未知及错误分类',
  `error_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '成功/拒绝/失败/未知及错误分类',
  `occurred_at` DATETIME(3) NOT NULL COMMENT '操作发生与 UTC 落库时间',
  `created_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT '操作发生与 UTC 落库时间',
  PRIMARY KEY (`id`),
  KEY `idx_admin_audit_log_target_type_t_bbe58d07` (`target_type`, `target_number`) COMMENT '查询索引 / 逻辑引用',
  KEY `idx_admin_audit_log_trace_id` (`trace_id`) COMMENT '查询索引 / 逻辑引用'
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='安全与业务操作审计';

-- audit / 安全事件
CREATE TABLE `admin_security_event_tab` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键及事件业务号',
  `security_event_number` VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键及事件业务号',
  `event_type_code` TINYINT UNSIGNED NOT NULL COMMENT '认证失败/越权/密钥异常/数据导出等分类；事件定义：SecurityEventDetected、IncidentTriaged、EvidenceCollected、ContainmentApplied、IncidentReviewed、IncidentResolved、AuditRecordAppended、确认误报、发生凭证/密钥泄露或持续越权、审计存储不可用/完整性校验失败；持久化编码仍须所属域明确。',
  `severity_code` TINYINT UNSIGNED NOT NULL COMMENT '认证失败/越权/密钥异常/数据导出等分类',
  `actor_reference` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '操作者及组织引用',
  `organization_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '操作者及组织引用',
  `source_ip` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '来源信息及设备指纹摘要',
  `device_fingerprint_hash` CHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '来源信息及设备指纹摘要',
  `target_reference` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '受影响资源业务引用',
  `event_status` TINYINT UNSIGNED NOT NULL COMMENT '新建/调查/关闭及处置动作；该字段独立码表待定义；不得使用概念流程标签或图示编号作为持久化枚举。',
  `response_action_code` TINYINT UNSIGNED NOT NULL COMMENT '新建/调查/关闭及处置动作',
  `detected_at` DATETIME(3) NOT NULL COMMENT '检测和关闭 UTC 时间',
  `resolved_at` DATETIME(3) NULL COMMENT '检测和关闭 UTC 时间',
  `evidence_reference` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '安全证据引用',
  `created_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'UTC 落库时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_admin_security_event_security__88d8e695` (`security_event_number`) COMMENT '业务唯一键 / 幂等键'
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='安全事件';

-- reporting / 指标定义
CREATE TABLE `report_metric_definition_tab` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键、指标码及定义版本',
  `metric_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键、指标码及定义版本',
  `version_number` INT NOT NULL COMMENT '主键、指标码及定义版本',
  `metric_name` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '指标名称和分组',
  `metric_group_code` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '指标名称和分组',
  `formula_reference` VARCHAR(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '受控公式实现引用及单位',
  `unit_code` VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '受控公式实现引用及单位',
  `currency_scope_code` TINYINT NOT NULL COMMENT '币种及发生日/会计日等口径',
  `date_basis_code` TINYINT NOT NULL COMMENT '币种及发生日/会计日等口径',
  `source_contexts_json` JSON NOT NULL COMMENT '数据源上下文和字段来源',
  `access_policy_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '权限/脱敏规则引用',
  `effective_from` DATETIME(3) NOT NULL COMMENT '定义有效区间',
  `effective_to` DATETIME(3) NULL COMMENT '定义有效区间',
  `approved_by` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '批准人及 UTC 时间',
  `approved_at` DATETIME(3) NULL COMMENT '批准人及 UTC 时间',
  `created_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'UTC 创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_report_metric_definition_metri_50c289eb` (`metric_code`, `version_number`) COMMENT '业务唯一键 / 幂等键'
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='指标定义';

-- reporting / 报表刷新快照
CREATE TABLE `report_snapshot_tab` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键及快照号',
  `snapshot_number` VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键及快照号',
  `metric_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '指标定义确定版本',
  `metric_version` INT NOT NULL COMMENT '指标定义确定版本',
  `scope_key` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '权限范围和过滤条件摘要',
  `filter_hash` CHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '权限范围和过滤条件摘要',
  `snapshot_at` DATETIME(3) NOT NULL COMMENT '统计时点与实际刷新 UTC 时间',
  `refreshed_at` DATETIME(3) NOT NULL COMMENT '统计时点与实际刷新 UTC 时间',
  `data_watermark_json` JSON NOT NULL COMMENT '各来源域已消费事件水位',
  `result_payload` JSON NOT NULL COMMENT '聚合值；金额以十进制字符串存储',
  `currency_code` CHAR(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '币种与日期范围',
  `business_date_from` DATE NOT NULL COMMENT '币种与日期范围',
  `business_date_to` DATE NOT NULL COMMENT '币种与日期范围',
  `source_hash` CHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '输入数据/规则摘要',
  `created_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'UTC 创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_report_snapshot_metric_code_sc_b5c24d93` (`metric_code`, `scope_key`, `snapshot_at`) COMMENT '业务唯一键 / 幂等键',
  CONSTRAINT `chk_report_snapshot_1` CHECK (currency_code = 'CNY')
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='报表刷新快照';

-- reporting / 报表导出任务
CREATE TABLE `report_export_job_tab` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键与导出业务号',
  `export_number` VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '主键与导出业务号',
  `idempotency_key` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '同一申请重试去重键',
  `requester_reference` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '申请人及授权快照',
  `role_snapshot` JSON NOT NULL COMMENT '申请人及授权快照',
  `metric_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL COMMENT '导出指标及冻结快照引用',
  `snapshot_number` VARCHAR(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '导出指标及冻结快照引用',
  `filter_snapshot_json` JSON NOT NULL COMMENT '查询范围和字段集合快照',
  `export_status` TINYINT UNSIGNED NOT NULL COMMENT '待审批/生成中/完成/失败/过期；该字段独立码表待定义；不得使用概念流程标签或图示编号作为持久化枚举。',
  `approval_reference` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '敏感导出审批引用',
  `file_reference` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '受控导出文件引用及摘要',
  `file_hash` CHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NULL COMMENT '受控导出文件引用及摘要',
  `expires_at` DATETIME(3) NULL COMMENT '过期和下载时间',
  `downloaded_at` DATETIME(3) NULL COMMENT '过期和下载时间',
  `created_at` DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'UTC 创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_report_export_job_export_number` (`export_number`) COMMENT '业务唯一键 / 幂等键',
  UNIQUE KEY `uk_report_export_job_idempotency_key` (`idempotency_key`) COMMENT '业务唯一键 / 幂等键'
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARACTER SET utf8mb4 COLLATE=utf8mb4_0900_bin COMMENT='报表导出任务';

