DELIMITER $$
CREATE TRIGGER `trg_tax_submission_freeze_content` BEFORE UPDATE ON `tax_submission_tab` FOR EACH ROW BEGIN IF NOT (OLD.`tax_case_number` <=> NEW.`tax_case_number`) OR NOT (OLD.`submission_revision_number` <=> NEW.`submission_revision_number`) OR NOT (OLD.`package_hash` <=> NEW.`package_hash`) OR NOT (OLD.`evidence_manifest_json` <=> NEW.`evidence_manifest_json`) OR NOT (OLD.`submission_content_json` <=> NEW.`submission_content_json`) OR NOT (OLD.`previous_submission_revision_number` <=> NEW.`previous_submission_revision_number`) OR NOT (OLD.`correction_event_number` <=> NEW.`correction_event_number`) OR NOT (OLD.`created_at` <=> NEW.`created_at`) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Frozen business content: tax_submission_tab'; END IF; END$$
DELIMITER ;

CREATE TRIGGER `trg_tax_submission_delete` BEFORE DELETE ON `tax_submission_tab` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Retained business history: tax_submission_tab';

DELIMITER $$
CREATE TRIGGER `trg_customs_filing_request_freeze_content` BEFORE UPDATE ON `customs_filing_request_tab` FOR EACH ROW BEGIN IF NOT (OLD.`request_number` <=> NEW.`request_number`) OR NOT (OLD.`declaration_number` <=> NEW.`declaration_number`) OR NOT (OLD.`revision_number` <=> NEW.`revision_number`) OR NOT (OLD.`action_code` <=> NEW.`action_code`) OR NOT (OLD.`request_hash` <=> NEW.`request_hash`) OR NOT (OLD.`request_payload_json` <=> NEW.`request_payload_json`) OR NOT (OLD.`created_by` <=> NEW.`created_by`) OR NOT (OLD.`created_at` <=> NEW.`created_at`) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Frozen business content: customs_filing_request_tab'; END IF; END$$
DELIMITER ;

CREATE TRIGGER `trg_customs_filing_request_delete` BEFORE DELETE ON `customs_filing_request_tab` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Retained business history: customs_filing_request_tab';
